:root {
  --bg: #1a1c2c;
  --card: #2a2d45;
  --text: #e0e0e0;
  --accent: #f4a261;
  --danger: #e76f51;
  --border: #4a4e69;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 8px;
  padding: 1.5rem;
  width: 100%;
  max-width: 420px;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.3);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.input-row {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

input[type="text"] {
  flex: 1;
  padding: 0.6rem;
  font-size: 1rem;
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  border-radius: 4px;
  outline: none;
}

input[type="text"]:focus {
  border-color: var(--accent);
}

button {
  font-family: inherit;
  font-size: 1rem;
  padding: 0.6rem 1rem;
  background: var(--accent);
  color: var(--bg);
  border: 3px solid var(--border);
  border-radius: 4px;
  cursor: pointer;
  font-weight: bold;
  transition: transform 0.05s, background 0.2s;
}

button:hover {
  background: #f4b261;
}

button:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.counts {
  display: flex;
  justify-content: space-between;
  margin-bottom: 1rem;
  font-size: 0.9rem;
  color: #a0a0b0;
}

.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem;
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 4px;
}

.task-item input[type="checkbox"] {
  width: 1.2rem;
  height: 1.2rem;
  accent-color: var(--accent);
  cursor: pointer;
}

.task-item span {
  flex: 1;
  word-break: break-word;
}

.task-item.completed span {
  text-decoration: line-through;
  opacity: 0.6;
}

.task-item button {
  padding: 0.3rem 0.6rem;
  background: var(--danger);
  font-size: 0.8rem;
}

.task-item button:hover {
  background: #f07f61;
}

@media (max-width: 400px) {
  .card {
    padding: 1rem;
  }
  h1 {
    font-size: 1.2rem;
  }
}

let tasks = [];
let nextId = 1;

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.completed).length;
}

function createTaskElement(task) {
  const li = document.createElement('li');
  li.className = 'task-item' + (task.completed ? ' completed' : '');
  li.dataset.id = task.id;

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = `todo-check-${task.id}`;
  checkbox.checked = task.completed;
  checkbox.setAttribute('aria-label', `Mark "${task.text}" as ${task.completed ? 'incomplete' : 'complete'}`);
  checkbox.addEventListener('change', () => {
    task.completed = checkbox.checked;
    li.classList.toggle('completed', task.completed);
    checkbox.setAttribute('aria-label', `Mark "${task.text}" as ${task.completed ? 'incomplete' : 'complete'}`);
    updateCounts();
  });

  const span = document.createElement('span');
  span.id = `todo-text-${task.id}`;
  span.textContent = task.text;

  const delBtn = document.createElement('button');
  delBtn.id = `todo-delete-${task.id}`;
  delBtn.textContent = 'Delete';
  delBtn.setAttribute('aria-label', `Delete task "${task.text}"`);
  delBtn.addEventListener('click', () => {
    tasks = tasks.filter(t => t.id !== task.id);
    li.remove();
    updateCounts();
  });

  li.append(checkbox, span, delBtn);
  return li;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const task = { id: nextId++, text, completed: false };
  tasks.push(task);
  list.appendChild(createTaskElement(task));
  input.value = '';
  input.focus();
  updateCounts();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', e => {
  if (e.key === 'Enter') addTask();
});

updateCounts();
